<?php
declare(strict_types=1);
require dirname(__DIR__).'/sistema/Nucleo/inicio.php';
$user=require_client();
$offers=query_rows('SELECT o.*,p.titulo,p.localidad,t.nombre AS operacion FROM ofertas_cliente o JOIN propiedades p ON p.id_propiedad=o.id_propiedad JOIN tipos_transaccion t ON t.id_tipo_transaccion=o.id_tipo_transaccion WHERE o.id_cliente=? ORDER BY o.fecha_creacion DESC',[$user['id']]);
$reservations=query_rows('SELECT r.*,p.titulo,p.localidad,t.nombre AS operacion FROM reservas r JOIN propiedades p ON p.id_propiedad=r.id_propiedad JOIN tipos_transaccion t ON t.id_tipo_transaccion=r.id_tipo_transaccion WHERE r.id_cliente=? ORDER BY r.fecha_reserva DESC',[$user['id']]);
$pageTitle='Mis ofertas y reservas';$activePage='ofertas';
require dirname(__DIR__).'/sistema/Vistas/Diseno/encabezado.php';
?>
<section class="dashboard"><div class="dashboard-title"><div><h1>Mis ofertas y reservas</h1><p>Consultá las respuestas del equipo y las fechas importantes.</p></div><a class="btn" href="/Inmobiliaria/index.php#catalogo">Explorar propiedades</a></div><div class="dash-layout"><?php require dirname(__DIR__).'/sistema/Vistas/Cliente/navegacion.php'; ?><main class="workspace"><?php notice(); ?><section class="content-card"><h2>Mis ofertas</h2><?php if($offers): ?><div class="table-wrap"><table class="table"><thead><tr><th>Propiedad</th><th>Operación</th><th>Monto</th><th>Enviada</th><th>Vencimiento</th><th>Estado</th><th>Respuesta</th></tr></thead><tbody><?php foreach($offers as $offer): $state=$offer['estado']==='Pendiente' && $offer['fecha_vencimiento'] && $offer['fecha_vencimiento']<date('Y-m-d')?'Vencida':$offer['estado']; ?><tr><td><strong><?= e($offer['titulo']) ?></strong><br><small><?= e($offer['localidad']) ?></small></td><td><?= e($offer['operacion']) ?></td><td><?= e($offer['moneda'].' '.number_format((float)$offer['monto'],2,',','.')) ?></td><td><?= e(date('d/m/Y',strtotime($offer['fecha_creacion']))) ?></td><td><?= e($offer['fecha_vencimiento']?date('d/m/Y',strtotime($offer['fecha_vencimiento'])):'—') ?></td><td><span class="status <?= $state==='Pendiente'?'amber':'blue' ?>"><?= e($state) ?></span></td><td><?= e($offer['observaciones']??'') ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>Todavía no enviaste ofertas. Podés ofertar desde el detalle de una propiedad disponible.</p><?php endif; ?></section>
<section class="content-card"><h2>Mis reservas</h2><?php if($reservations): ?><div class="table-wrap"><table class="table"><thead><tr><th>Propiedad</th><th>Operación</th><th>Fecha límite</th><th>Pago</th><th>Estado</th><th>Observaciones</th></tr></thead><tbody><?php foreach($reservations as $reservation): ?><tr><td><?= e($reservation['titulo']) ?></td><td><?= e($reservation['operacion']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($reservation['fecha_limite']))) ?></td><td><?= e($reservation['estado_pago'].' · '.($reservation['medio_pago']?:'Sin informar')) ?></td><td><span class="status <?= $reservation['estado']==='Pendiente'?'amber':'blue' ?>"><?= e($reservation['estado']) ?></span></td><td><?= e($reservation['observaciones']??'') ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No tenés reservas registradas.</p><?php endif; ?></section></main></div></section>
<?php require dirname(__DIR__).'/sistema/Vistas/Diseno/pie.php'; ?>
